@php $editing=isset($campaign); @endphp<form class="portal-form" method="post" action="{{ $editing?route('admin.newsletter.campaigns.update',$campaign):route('admin.newsletter.campaigns.store') }}" data-loading>@csrf @if($editing)@method('put')@endif<div class="portal-field"><label for="subject">Email subject</label><input class="portal-input" id="subject" name="subject" value="{{ old('subject',$campaign->subject??'') }}" required><x-portal.field-error name="subject" /></div><div class="portal-field"><label for="preview_text">Inbox preview text</label><input class="portal-input" id="preview_text" name="preview_text" value="{{ old('preview_text',$campaign->preview_text??'') }}"></div><x-portal.rich-editor name="content" id="content" label="Campaign content" :value="old('content',$campaign->content??'')" required /><div class="portal-field"><label for="scheduled_for">Schedule time <span>required only when scheduling</span></label><input class="portal-input" id="scheduled_for" name="scheduled_for" type="datetime-local" min="{{ now()->addMinute()->format('Y-m-d\TH:i') }}" value="{{ old('scheduled_for',isset($campaign)&&$campaign->scheduled_for?$campaign->scheduled_for->format('Y-m-d\TH:i'):'') }}"><x-portal.field-error name="scheduled_for" /></div><div class="form-actions"><a class="portal-button" href="{{ route('admin.newsletter.index') }}">Cancel</a><button class="portal-button" name="action" value="draft" type="submit">Save draft</button><button class="portal-button" name="action" value="schedule" type="submit">Schedule</button><button class="portal-button primary" name="action" value="send" type="submit" data-loading-text="Queueing…">Send now</button></div></form>
